const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  const body = $input.first().json.body || {};
  const approvalId = body.approval_id;
  const decision = body.decision; // 'approve' | 'reject'
  const notes = body.notes || null;
  if (!approvalId || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(approvalId)) {
    return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'approval_id (UUID) requerido' } }];
  }
  if (decision !== 'approve' && decision !== 'reject') {
    return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'decision debe ser approve o reject' } }];
  }
  const newStatus = decision === 'approve' ? 'approved' : 'rejected';
  return [{ json: {
    user_id:     payload.sub,
    tenant_id:   payload.tenant_id || null,
    role:        payload.role || 'architect',
    email:       payload.email || null,
    full_name:   payload.full_name || null,
    approval_id: approvalId,
    decision,
    new_status:  newStatus,
    notes,
    request_id:  'req_' + Math.random().toString(36).slice(2, 10)
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const row = $input.first()?.json;
const sess = $('Decode JWT + Body').first().json;
if (!row || !row.id) {
  return [{ json: {
    _error: 'NOT_FOUND',
    _status: 404,
    _details: 'Approval no encontrado, no es pending o sin permisos para este tenant',
    request_id: sess.request_id
  }}];
}
return [{ json: {
  data: {
    approval_id:    row.id,
    project_id:     row.project_id,
    approval_type:  row.approval_type,
    status:         row.status,
    decided_at:     row.decided_at,
    decided_by:     row.decided_by
  },
  meta: {
    request_id: sess.request_id,
    timestamp:  new Date().toISOString(),
    warnings: [
      'Decision registrada en BD. El flujo n8n Wait sigue bloqueado hasta clic en email — desbloqueo via UI requiere migracion futura (resume_webhook_url en approvals).'
    ]
  }
}}];
